```R
# Function to convert character vector to numeric and check for NA values
is_numeric_vector <- function(x) {
  tryCatch({
    as.numeric(x[!is.na(x)])
    TRUE
  }, error = function(e) FALSE)
}

# Example usage
x <- c("1", "2", "3", "4", NA, "5")
