```typescript
import * as Chart from 'chart.js';

interface Dataset {
  label: string;
  data: number[];
  backgroundColor: string[];
}

function generateBarChart(dataset: Dataset) {
  const ctx = document.getElementById('bar-chart')!.getContext('2d');
  const myChart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: dataset.data.map((_, index) => index),
      datasets: [{
        label: dataset.label,
        data: dataset.data,
        backgroundColor: dataset.backgroundColor,
      }],
    },
    options: {
      scales: {
        y: {
          beginAtZero: true,
        },
      },
    },
  });
}

// Example usage
const dataset: Dataset = {
  label: 'Sales',
  data: [10, 20, 30, 40, 50],
  backgroundColor: ['#FF6384', '#36A2EB', '#FFCE56', '#FFF59D', '#FF5733'],
};
generateBarChart(dataset);
```

To use this program, you'll need to include the Chart.js library in your project and add the `bar-chart` element to your HTML file. You can then call the `generateBarChart` function with your dataset to create the bar chart.

