Here's the code for the `redis.js` file inside the `utils` folder:

```javascript
// redis.js
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: 'localhost',
      port: 6379,
      db: 0,
    });

    this.client.on('error', (err) => {
      console.error('Error with Redis client:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error('Error checking Redis connection:', err);
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error('Error getting from Redis:', err);
      throw err;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
      return true;
    } catch (err) {
      console.error('Error setting in Redis:', err);
      throw err;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
      return true;
    } catch (err) {
      console.error('Error deleting from Redis:', err);
      throw err;
    }
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

This code defines a `RedisClient` class that wraps around an instance of `ioredis`. It provides methods for checking the connection, getting and setting values, and deleting keys in Redis. The `redisClient` variable is created and exported as an instance of the `RedisClient` class.

